import type { CaptionStyle, CaptionTrack, TextTrackInfo } from "../../core/types.js";

function trackId(track: TextTrack, index: number): string {
  return track.id.length > 0 ? track.id : `text-${index}`;
}

/** Reads the text tracks exposed by a media element. */
export function toTextTrackInfos(media: HTMLMediaElement): readonly TextTrackInfo[] {
  const tracks: TextTrackInfo[] = [];
  const textTracks = (media as HTMLMediaElement & { readonly textTracks?: TextTrackList })
    .textTracks;

  if (textTracks === undefined) {
    return tracks;
  }

  for (let index = 0; index < textTracks.length; index += 1) {
    const track = textTracks[index];

    if (track === undefined) {
      continue;
    }

    tracks.push({
      id: trackId(track, index),
      label: track.label.length > 0 ? track.label : `Track ${index + 1}`,
      language: track.language,
      kind: track.kind as TextTrackInfo["kind"],
      default: track.mode === "showing",
    });
  }

  return tracks;
}

/** Shows one text track and disables the rest. */
export function selectTextTrack(media: HTMLMediaElement, id: string | null): void {
  const textTracks = (media as HTMLMediaElement & { readonly textTracks?: TextTrackList })
    .textTracks;

  if (textTracks === undefined) {
    return;
  }

  for (let index = 0; index < textTracks.length; index += 1) {
    const track = textTracks[index];

    if (track === undefined) {
      continue;
    }

    track.mode = id !== null && trackId(track, index) === id ? "showing" : "disabled";
  }
}

/** Returns the caption track with the given id, or null. */
export function findTextTrack(
  tracks: readonly TextTrackInfo[],
  id: string | null,
): TextTrackInfo | null {
  if (id === null) {
    return null;
  }

  return tracks.find((track) => track.id === id) ?? null;
}

/** Cycles through off and every available track. */
export function nextTextTrackId(
  tracks: readonly TextTrackInfo[],
  currentId: string | null,
): string | null {
  if (tracks.length === 0) {
    return null;
  }

  if (currentId === null) {
    return tracks[0]?.id ?? null;
  }

  const index = tracks.findIndex((track) => track.id === currentId);
  const next = index < 0 ? 0 : index + 1;
  return next >= tracks.length ? null : (tracks[next]?.id ?? null);
}

/** A YouTube-style "Off + languages" caption menu model. */
export interface CaptionMenuItem {
  readonly id: string | null;
  readonly label: string;
  readonly language: string;
  readonly kind: TextTrackInfo["kind"];
  readonly selected: boolean;
}

/** Builds the caption menu, always including an explicit Off entry. */
export function captionMenuItems(
  tracks: readonly TextTrackInfo[],
  currentId: string | null,
  offLabel = "Off",
): readonly CaptionMenuItem[] {
  const items: CaptionMenuItem[] = [
    {
      id: null,
      label: offLabel,
      language: "",
      kind: "subtitles",
      selected: currentId === null,
    },
  ];

  for (const track of tracks) {
    items.push({
      id: track.id,
      label: track.label,
      language: track.language,
      kind: track.kind,
      selected: track.id === currentId,
    });
  }

  return items;
}

/** Converts a consumer caption track to the native `<track>` attributes. */
export interface CaptionTrackElementOptions {
  readonly id: string;
  readonly src: string;
  readonly label: string;
  readonly language: string;
  readonly kind: string;
  readonly default: boolean;
}

/** Normalizes source/option caption tracks for the native engine. */
export function toCaptionTrackElements(
  tracks: readonly CaptionTrack[],
  fallbackIdPrefix = "caption",
): readonly CaptionTrackElementOptions[] {
  return tracks.map((track, index) => ({
    id: track.id ?? `${fallbackIdPrefix}-${index}`,
    src: track.src,
    label: track.label,
    language: track.language,
    kind: track.kind ?? "subtitles",
    default: track.default === true,
  }));
}

/** Maps caption styling to CSS custom properties. */
export function captionStyleDeclarations(style: CaptionStyle): Readonly<Record<string, string>> {
  const declarations: Record<string, string> = {};

  if (style.fontSize !== undefined) {
    declarations["--up-caption-size"] = style.fontSize;
  }

  if (style.color !== undefined) {
    declarations["--up-caption-color"] = style.color;
  }

  if (style.background !== undefined) {
    declarations["--up-caption-background"] = style.background;
  }

  if (style.opacity !== undefined) {
    declarations["--up-caption-opacity"] = String(Math.min(Math.max(style.opacity, 0), 1));
  }

  if (style.edge !== undefined) {
    declarations["--up-caption-edge"] = style.edge;
  }

  if (style.fontFamily !== undefined) {
    declarations["--up-caption-font"] = style.fontFamily;
  }

  return declarations;
}
